namespace bo3z::codex
{
	struct Chapter { int book; std::string_view title, image; std::vector<std::string_view> paras; };
	inline constexpr std::array<std::string_view, 15> kBooks{ "The Curse of Alduin", "The Summoner's Path", "The Battle-mage's Path", "The Ranger's Path", "The Spellsword's Path", "The Broken Words: Riverwood", "The Broken Words: Whiterun", "The Broken Words: Solitude", "The Broken Words: Windhelm", "The Broken Words: Markarth", "The Broken Words: Riften", "The Broken Words: Falkreath", "The Broken Words: Morthal", "The Broken Words: Dawnstar", "The Broken Words: Winterhold" };  // 0 the lore, 1-4 the class guides (Summoner, Destruction, Ranger, Spellsword), 5+ a freed city's page (kTowns order)
	inline const std::vector<Chapter> kChapters{
		{ 0, "The Greybeard's Account", "sigil", { "Written at High Hrothgar by a Greybeard who broke his silence, for whoever lived through Helgen" } },
		{ 0, "I. What Happened", "helgen", { "When Alduin rose over Helgen, he shouted three Words into the earth: <b>SLEN TIID VO</b> - Flesh, Time, Undo. It is the shout that raises the dead.", "His mist also covers the door of <b>Sovngarde</b>, so the dead of Skyrim cannot pass on. They lie restless in the ground. By day they sleep. When the sun goes down, they rise." } },
		{ 0, "II. The Dead", "graves", { "Each night the dead come in <b>waves</b>, more of them and harder to kill as the nights go on. They claw up out of open ground - roads and fields, never inside a house - and come at you from every side. Dawn comes only when the last wave falls.", "The curse's whole host walks with them, each under its own name. Mihail's zombies and the Thriceborn come first with the Rag Draugr, rotten skeletons and plague wolves; then Bonemen, skeleton mages and the necromancers who serve the curse - kill those first, for they raise more; then Hulking Draugr, Draugr Liches, Draman Brutes, Ash Spawn and werewolves; and at the last the Daedra and the Overlords.", "Some nights the noise you make draws a hunter that comes through a portal and pounces. The Curse's champions and great ones step out of portals too - and their names burn gold over their heads." } },
		{ 0, "III. The Echo Altars", "wards", { "Long ago the <b>Tongues</b>, the first masters of the Voice, raised an altar in every hold to hold Alduin's shout back. Every mage who fell in the Dragon War gave a last spell to them, which is why an altar still has spells, bows and gifts to give.", "Alduin's return woke the altars only halfway. Each one is held silent by a <b>Dragon Priest</b>, still bound by his old oath to Alduin." } },
		{ 0, "IV. Waking an Altar", "", { "Stand at an altar and it sets you <b>trials</b>: hold its rune circle, cull the dead in its streets, hold the altar through a night's waves, and pass the trial of your own path. Finish them and its Dragon Priest rises at night. Kill him and the altar wakes.", "A woken altar makes its city a <b>sanctuary</b>: none of the curse's dead rise inside it, by night or by day. Step outside its walls and they find you again." } },
		{ 0, "V. The Dragonborn's Road", "", { "The Curse walks beside your own story; it does not replace it.", "<b>Riverwood's</b> altar, nearest Helgen, wakes first. <b>Whiterun's</b> answers your first dragon soul and gives you a dragon to ride - and its Thu'um, <i>Dragon's Updraft</i>. <b>Solitude's</b> bards give you the <i>Dance of Death</i>.", "Free six cities and each path's <b>secret</b> wakes. Win it and the Greybeards call you to <b>High Hrothgar</b>: your path's <b>wonder</b> waits on its pedestal in the Reliquary beneath the great hall.", "With all four wonders won - alone or with friends - Alduin's three Words wake as <b>dragons</b>: <b>SLEN</b> in the Reach, <b>TIID</b> at Labyrinthian and <b>VO</b> on Mount Anthor. Slay all three, wake every altar, and only his <b>Echo</b> is left, on the summit of the Throat of the World. End it, and the Curse is broken." } },
		{ 0, "VI. The Voices of the Holds", "", { "<b>Whiterun</b>: <i>Dragon's Updraft</i>. A whirlwind lifts you high - and a dragon to carry you.", "<b>Solitude</b>: <i>Dance of Death</i>. The dead near you dance, helpless, and take half again as much harm. Once a wave." } },
		{ 0, "Epilogue", "", { "Every Echo Altar in Skyrim is awake. Alduin's voice lingers only in the wild places now - and in the echo he left on the Throat of the World.", "<i>- written in the silence of High Hrothgar</i>" } },
		{ 1, "The Summoner", "", { "A conjurer of the <b>College of Winterhold</b>. Your summons fight for you - every kill they make is yours: Cursed Essence, progress and trials.", "<b>You start with</b> Conjure Wolf (left hand), Conjure Skeleton in your spellbook, the <b>Riftblade</b> (right hand) and the <b>Arcane Conjurer Robes</b> (your armor set: Tier I your summons take a fifth less, Tier II one more summon slot, Tier III your summons' kills heal you). Every Riftblade hit marks that enemy for your summons. Every 5th hit tears a rift and a Flame Atronach fights for you for 10 s - every 4th at Tier I (15 s), every 3rd at Tier II (a Flame, Frost or Storm Atronach, three at once); at Tier III the dead it kills rise as your thralls and every 10th hit a Dremora steps out." } },
		{ 1, "Your Progress", "@progress", {  } },
		{ 1, "Your Altar", "", { "<b>Your kit</b> - each item with its tier and the price of its next upgrade. Select one to upgrade it.", "<b>The Armory</b> - more summon families open as you free cities: <b>Dwemer</b> at 1, <b>Atronachs</b> at 2, <b>the Wild</b> at 3, <b>Ash</b> at 4, <b>Daedra</b> at 5, <b>the Night</b> at 7, <b>the Wrath</b> at 9. You keep every family you buy.", "<b>Dragon Priest relics</b> - every Dragon Priest you slay leaves a relic for your class. Take it at any Echo Altar. The Summoner's relics are the heroes and armies of old: Ysgramor, Gormlaith, Felldir, Hakon, Miraak, Karstaag, the Ebony Warrior, and four great armies." } },
		{ 1, "Getting Stronger", "", { "<b>One curve for everything.</b> Every item in your kit climbs Base, <b>Tier I</b> (1.3 times its damage), <b>Tier II</b> (1.7 times), <b>Tier III - Legendary</b> (2.2 times), then <b>Ascends</b> (+0.3 times each). Prices: Tier I 4,000, Tier II 6,000 (needs 2 freed cities), Tier III 8,000 (4 cities), Ascend 10,000 and 2,000 more each time (6 cities). Your class's <b>armor set</b> is in your kit too: it starts at 5% damage reduction and every tier adds 5% (20% at Tier III), with a power of its own at each tier; each Ascend of the set adds 5% to all your damage.", "<b>Summon slots</b> - how many summons you can have out at the same time. You start with <b>2</b>; the Conjurer's Command Mead adds one and your robes' Tier II one more - <b>4</b> at most. When every slot is full, a new summon replaces your oldest one." } },
		{ 1, "Your Perks", "", { "<b>Bonebinder's Brew</b> - your summons have 30% more health and deal 30% more damage.", "<b>Soul-Tether Wine</b> - each time one of your summons kills an enemy, you heal 3% of your maximum health.", "<b>Conjurer's Command Mead</b> - one more summon slot (up to 4).", "One of each perk a life - death takes them all." } },
		{ 1, "Your Trial and Wonder", "", { "<b>Pact of the Host</b> (your city trial): let your summons make the kills - 20 on Novice up to 60 on Legendary.", "<b>Horn of the Spectral Wyrm</b> (your wonder): it can't be rolled or bought. Once six cities are freed, your path's <b>secret</b> wakes - a long hidden quest played from altar to altar, never twice in a row in the same city. Listen to the freed altars' whispers. When it is won the Greybeards call: the wonder waits on its pedestal in the Reliquary beneath High Hrothgar. It calls a spectral dragon for a minute - once the three dragons fall, it stays until it is slain." } },
		{ 1, "How a Night Works", "", { "<b>Day</b> (about 20 minutes): the dead sleep. Explore, rest and spend your Cursed Essence.", "<b>Night</b>: the dead claw up out of the ground (on open ground, never in houses) in <b>waves</b> - fast runners, more and tougher each night, coming from every side. Elites and bosses step out of the Curse's portals. Dawn only comes when the last wave falls.", "The night's dead are the curse's whole host, each under its own name: Mihail's zombies and the Thriceborn walk first with the Rag Draugr, rotten skeletons and plague wolves; then Bonemen, skeleton mages and the necromancers who serve the curse; then Hulking Draugr, Draugr Liches, Draman Brutes, Ash Spawn and werewolves; then the Daedra - Clannfear, Daedroth, Dremora - and at the last the Overlords, the Mythic Liches and the Skeleton Reaper Warlords. Casters keep back and raise more dead - kill them first.", "Some nights the noise you make draws a hunter: a feral nightwalker, far faster than the rest, that comes through a portal and pounces.", "Busy with a quest? Open the wait menu at night, once the countdown has ended, and choose <b>Skip the Night</b>. It passes the whole night to dawn and does not count: no night survived, and the next dusk brings the same night again.", "<b>Cursed Essence</b> drops from every kill - spend it at the Echo Altars. Now and then a body drops a glowing token (1 kill in 50): walk into it before it blinks out (20 s). Nuke (the dead around you turn to ash), Double Essence (30 s), Refill Stats (ammo, health, magicka, stamina and your shout), Merchant's Blessing (the altars at half price, 45 s), Shadow of Nocturnal (the dead lose you, 15 s), Thu'um Unbound (no shout cooldown, 20 s) and Kynareth's Mercy (everyone healed, a fallen friend lifted). In a party, what one takes everyone gets. From dusk to dawn a lantern at your belt lights 20 metres round you. At dawn the dead leave their ash where they fell, and in a freed city its people leave an offering at their altar for you each day.", "Your health, magicka and stamina sit on one plate at the bottom; its rim glows blue while your shout recovers." } },
		{ 1, "The Echo Altar", "", { "Every city has one. Step onto it and activate it. Move with the D-pad or W/S, choose with A or Enter, leave with B.", "From the top: <b>your class</b> (change it for Cursed Essence - each class keeps its own kit and progress), a <b>Dragon Priest's relic</b> when one waits, then sections that open one at a time: <b>Your Kit</b> (select an item to upgrade it), <b>the Armory</b> (new items, opened by freed cities), <b>Perks</b>, <b>Your Dragon</b>, the city's <b>Trials</b> and the <b>Whispers</b> of your path's secret.", "<b>Freeing a city</b>: finish four trials (three shared, one your class's), then slay its <b>Dragon Priest</b>, who rises at night. Its fall ends the night and leaves a relic. A freed city is a sanctuary: none of the curse's dead rise inside it. Whiterun gives you a dragon to ride and Dragon's Updraft; Solitude gives you the Dance of Death.", "<b>Every 5th night</b> a great boss walks with the dead - and its dawn leaves a power-up at your feet." } },
		{ 1, "The Road to the Echo", "", { "<b>The Reliquary</b>: once six cities are free, your path's <b>secret</b> wakes. Win it and the Greybeards call you - your <b>wonder</b> waits on its pedestal in the Reliquary, behind the sealed door in High Hrothgar's great hall. A wonder answers only to its own path.", "<b>The three dragons</b>: with all four paths' wonders won (change class to win each, or pool them with your party), Alduin's three words wake as dragons - <b>SLEN</b> at the cult's shrine in the Reach, <b>TIID</b> at Labyrinthian, <b>VO</b> on Mount Anthor. Go at night: the dead come first, then the dragon. Each one slain gives a lasting power, and with all three dead your wonders take their <b>Legendary</b> form.", "<b>The Echo of Alduin</b>: last of all, once the three dragons are dead and every Echo Altar is awake, on the summit of the Throat of the World. Slay it and the curse is broken - the nights are only nights again, and the Reliquary becomes the <b>Hall of the Awakened</b>: Alduin's Bane, the First Dragonborn's Regalia, the Bone-Wyrm's Skull, the Brazier of the Endless Night and the Seat of the Awakened." } },
		{ 1, "Settings", "", { "<b>Difficulty</b> is Skyrim's own (Settings, Gameplay). Novice is very easy, Apprentice easy, Adept normal, Expert hard, Master very hard and Legendary close to impossible. From Novice to Legendary the dead (and Skyrim's own foes against your altar gear) have <b>0.5x, 0.75x, 1x, 1.5x, 2.2x, 3.2x</b> health, and the dead hit <b>0.4x, 0.65x, 1x, 1.4x, 1.9x, 2.6x</b> as hard. Every Echo Altar freed makes them all 30% tougher (up to ten), to keep up with your upgraded gear. Until three altars are freed, on Adept or harder, no single hit takes more than 60% of a zombie's health.", "Skyrim's own enemies get tougher with the difficulty and with every altar you free, so they keep up with you.", "The <b>Mod Configuration Menu</b> page <i>The Curse of Alduin</i> has the rest: attack and draw speed, field of view, brightness, effects and controls." } },
		{ 2, "The Battle-mage", "", { "A battle-mage of the <b>College of Winterhold</b>: a different element in each hand, struck from afar - bolts, beams, storms and runes.", "<b>You start with</b> Firebolt (right hand), Ice Spike (left hand), a Destruction tome and the <b>Black Mage Robes</b> - your armor set, its look growing at each tier (Mantled Robes, Plate, then the Black Archmage's ebony): Tier I spells cost 10% less, Tier II magicka comes back faster, Tier III spells cost a quarter less. Your magicka starts coming back 1 second after a cast." } },
		{ 2, "Your Progress", "@progress", {  } },
		{ 2, "Your Altar", "", { "<b>Your kit</b> - each element with its tier and the price of its next upgrade: each tier is the next spell of its ladder (Firebolt, Fireball, Incinerate, Immolate).", "<b>The Armory</b> - more elements open as you free cities: <b>Shock</b> at 1, <b>Cloaks</b> at 2, <b>Sun</b> at 3, <b>Walls</b> at 4, <b>Blood</b> at 5, <b>Runes</b> at 7, <b>Storms</b> at 9.", "<b>Dragon Priest relics</b> - every Dragon Priest you slay leaves a relic for your class. Take it at any Echo Altar. Destruction's relics are the support spells: Ash Cloud, Cinder Storm, Charged Nova and Symmetry." } },
		{ 2, "Getting Stronger", "", { "<b>One curve for everything.</b> Every item in your kit climbs Base, <b>Tier I</b> (1.3 times its damage), <b>Tier II</b> (1.7 times), <b>Tier III - Legendary</b> (2.2 times), then <b>Ascends</b> (+0.3 times each). Prices: Tier I 4,000, Tier II 6,000 (needs 2 freed cities), Tier III 8,000 (4 cities), Ascend 10,000 and 2,000 more each time (6 cities). Your class's <b>armor set</b> is in your kit too: it starts at 5% damage reduction and every tier adds 5% (20% at Tier III), with a power of its own at each tier; each Ascend of the set adds 5% to all your damage." } },
		{ 2, "Your Perks", "", { "<b>Ember Heart Ale</b> - Destruction kills burst and hurt the dead nearby.", "<b>Arcanist's Focus Tea</b> - Destruction spells cost 25% less magicka.", "<b>Mana-Siphon Draught</b> - each Destruction kill gives back 4% magicka.", "One of each perk a life - death takes them all." } },
		{ 2, "Your Trial and Wonder", "", { "<b>Trial of the Elements</b> (your city trial): kill with two or more elements - 20 on Novice up to 60 on Legendary.", "<b>Tome of the Six Fires</b> (your wonder): it can't be rolled or bought. Once six cities are freed, your path's <b>secret</b> wakes - a long hidden quest played from altar to altar, never twice in a row in the same city. Listen to the freed altars' whispers. When it is won the Greybeards call: the wonder waits on its pedestal in the Reliquary beneath High Hrothgar. One cast looses the top spell of all six elements on the dead around you, every 8 seconds - once the three dragons fall, the fires burn hotter and their third rungs come too." } },
		{ 2, "How a Night Works", "", { "<b>Day</b> (about 20 minutes): the dead sleep. Explore, rest and spend your Cursed Essence.", "<b>Night</b>: the dead claw up out of the ground (on open ground, never in houses) in <b>waves</b> - fast runners, more and tougher each night, coming from every side. Elites and bosses step out of the Curse's portals. Dawn only comes when the last wave falls.", "The night's dead are the curse's whole host, each under its own name: Mihail's zombies and the Thriceborn walk first with the Rag Draugr, rotten skeletons and plague wolves; then Bonemen, skeleton mages and the necromancers who serve the curse; then Hulking Draugr, Draugr Liches, Draman Brutes, Ash Spawn and werewolves; then the Daedra - Clannfear, Daedroth, Dremora - and at the last the Overlords, the Mythic Liches and the Skeleton Reaper Warlords. Casters keep back and raise more dead - kill them first.", "Some nights the noise you make draws a hunter: a feral nightwalker, far faster than the rest, that comes through a portal and pounces.", "Busy with a quest? Open the wait menu at night, once the countdown has ended, and choose <b>Skip the Night</b>. It passes the whole night to dawn and does not count: no night survived, and the next dusk brings the same night again.", "<b>Cursed Essence</b> drops from every kill - spend it at the Echo Altars. Now and then a body drops a glowing token (1 kill in 50): walk into it before it blinks out (20 s). Nuke (the dead around you turn to ash), Double Essence (30 s), Refill Stats (ammo, health, magicka, stamina and your shout), Merchant's Blessing (the altars at half price, 45 s), Shadow of Nocturnal (the dead lose you, 15 s), Thu'um Unbound (no shout cooldown, 20 s) and Kynareth's Mercy (everyone healed, a fallen friend lifted). In a party, what one takes everyone gets. From dusk to dawn a lantern at your belt lights 20 metres round you. At dawn the dead leave their ash where they fell, and in a freed city its people leave an offering at their altar for you each day.", "Your health, magicka and stamina sit on one plate at the bottom; its rim glows blue while your shout recovers." } },
		{ 2, "The Echo Altar", "", { "Every city has one. Step onto it and activate it. Move with the D-pad or W/S, choose with A or Enter, leave with B.", "From the top: <b>your class</b> (change it for Cursed Essence - each class keeps its own kit and progress), a <b>Dragon Priest's relic</b> when one waits, then sections that open one at a time: <b>Your Kit</b> (select an item to upgrade it), <b>the Armory</b> (new items, opened by freed cities), <b>Perks</b>, <b>Your Dragon</b>, the city's <b>Trials</b> and the <b>Whispers</b> of your path's secret.", "<b>Freeing a city</b>: finish four trials (three shared, one your class's), then slay its <b>Dragon Priest</b>, who rises at night. Its fall ends the night and leaves a relic. A freed city is a sanctuary: none of the curse's dead rise inside it. Whiterun gives you a dragon to ride and Dragon's Updraft; Solitude gives you the Dance of Death.", "<b>Every 5th night</b> a great boss walks with the dead - and its dawn leaves a power-up at your feet." } },
		{ 2, "The Road to the Echo", "", { "<b>The Reliquary</b>: once six cities are free, your path's <b>secret</b> wakes. Win it and the Greybeards call you - your <b>wonder</b> waits on its pedestal in the Reliquary, behind the sealed door in High Hrothgar's great hall. A wonder answers only to its own path.", "<b>The three dragons</b>: with all four paths' wonders won (change class to win each, or pool them with your party), Alduin's three words wake as dragons - <b>SLEN</b> at the cult's shrine in the Reach, <b>TIID</b> at Labyrinthian, <b>VO</b> on Mount Anthor. Go at night: the dead come first, then the dragon. Each one slain gives a lasting power, and with all three dead your wonders take their <b>Legendary</b> form.", "<b>The Echo of Alduin</b>: last of all, once the three dragons are dead and every Echo Altar is awake, on the summit of the Throat of the World. Slay it and the curse is broken - the nights are only nights again, and the Reliquary becomes the <b>Hall of the Awakened</b>: Alduin's Bane, the First Dragonborn's Regalia, the Bone-Wyrm's Skull, the Brazier of the Endless Night and the Seat of the Awakened." } },
		{ 2, "Settings", "", { "<b>Difficulty</b> is Skyrim's own (Settings, Gameplay). Novice is very easy, Apprentice easy, Adept normal, Expert hard, Master very hard and Legendary close to impossible. From Novice to Legendary the dead (and Skyrim's own foes against your altar gear) have <b>0.5x, 0.75x, 1x, 1.5x, 2.2x, 3.2x</b> health, and the dead hit <b>0.4x, 0.65x, 1x, 1.4x, 1.9x, 2.6x</b> as hard. Every Echo Altar freed makes them all 30% tougher (up to ten), to keep up with your upgraded gear. Until three altars are freed, on Adept or harder, no single hit takes more than 60% of a zombie's health.", "Skyrim's own enemies get tougher with the difficulty and with every altar you free, so they keep up with you.", "The <b>Mod Configuration Menu</b> page <i>The Curse of Alduin</i> has the rest: attack and draw speed, field of view, brightness, effects and controls." } },
		{ 3, "The Ranger", "", { "Sworn to the <b>Dawnguard</b>. Bows and crossbows - every arrow counts.", "<b>You start with</b> the Ember Crossbow and its bolts, the <b>Emberstring</b> bow, and the <b>Gondorian Ranger Armor</b> (your armor set: Tier I you move 10% faster, Tier II your arrows and bolts come back faster, Tier III a kill from 30 m or more puts stamina back). You carry one crossbow and one bow; the rest wait in your class's chest - select one in your kit to take it up." } },
		{ 3, "Your Progress", "@progress", {  } },
		{ 3, "Your Altar", "", { "<b>Your kit</b> - each bow and crossbow with its tier and the price of its next upgrade.", "<b>The Armory</b> - as you free cities: the <b>Rime Crossbow</b> at 1, <b>Rimehorn</b> at 2, the <b>Storm Crossbow</b> at 3, <b>Stormreach</b> at 4, <b>Skyhowl</b> at 6, <b>Dawnspire</b> at 8, <b>Thirstbow</b> at 9.", "<b>Dragon Priest relics</b> - every Dragon Priest you slay leaves a relic for your class. Take it at any Echo Altar. The Ranger's relics are three quivers that make your bows' and crossbows' blasts reach wider." } },
		{ 3, "Getting Stronger", "", { "<b>One curve for everything.</b> Every item in your kit climbs Base, <b>Tier I</b> (1.3 times its damage), <b>Tier II</b> (1.7 times), <b>Tier III - Legendary</b> (2.2 times), then <b>Ascends</b> (+0.3 times each). Prices: Tier I 4,000, Tier II 6,000 (needs 2 freed cities), Tier III 8,000 (4 cities), Ascend 10,000 and 2,000 more each time (6 cities). Your class's <b>armor set</b> is in your kit too: it starts at 5% damage reduction and every tier adds 5% (20% at Tier III), with a power of its own at each tier; each Ascend of the set adds 5% to all your damage.", "Each tier: more damage, a new attack and a bigger quiver - <b>60</b>, <b>100</b>, <b>150</b>, <b>200</b> arrows. You never run dry: an empty quiver grows back one a second once you have stopped shooting for 5 seconds.", "<b>Crossbows</b>: kills unlock elemental bolts - fire at 25, ice at 60, shock at 120." } },
		{ 3, "Your Perks", "", { "<b>Fletcher's Sap Draught</b> - your arrows or bolts slowly grow back.", "<b>Eagle-Eye Draught</b> - bows draw and crossbows reload 20% faster.", "<b>Dawnwatch Tonic</b> - with a bow or crossbow out, the dead hurt you 20% less.", "One of each perk a life - death takes them all." } },
		{ 3, "Your Trial and Wonder", "", { "<b>Trial of the Long Shot</b> (your city trial): bow or crossbow kills from 30 m or more - 10 on Novice up to 30 on Legendary.", "<b>The Subsuming Vortex</b> (your wonder): it can't be rolled or bought. Once six cities are freed, your path's <b>secret</b> wakes - a long hidden quest played from altar to altar, never twice in a row in the same city. Listen to the freed altars' whispers. When it is won the Greybeards call: the wonder waits on its pedestal in the Reliquary beneath High Hrothgar. Its arrows open black holes that drag the dead in, then burst - wider and stronger once the three dragons fall." } },
		{ 3, "How a Night Works", "", { "<b>Day</b> (about 20 minutes): the dead sleep. Explore, rest and spend your Cursed Essence.", "<b>Night</b>: the dead claw up out of the ground (on open ground, never in houses) in <b>waves</b> - fast runners, more and tougher each night, coming from every side. Elites and bosses step out of the Curse's portals. Dawn only comes when the last wave falls.", "The night's dead are the curse's whole host, each under its own name: Mihail's zombies and the Thriceborn walk first with the Rag Draugr, rotten skeletons and plague wolves; then Bonemen, skeleton mages and the necromancers who serve the curse; then Hulking Draugr, Draugr Liches, Draman Brutes, Ash Spawn and werewolves; then the Daedra - Clannfear, Daedroth, Dremora - and at the last the Overlords, the Mythic Liches and the Skeleton Reaper Warlords. Casters keep back and raise more dead - kill them first.", "Some nights the noise you make draws a hunter: a feral nightwalker, far faster than the rest, that comes through a portal and pounces.", "Busy with a quest? Open the wait menu at night, once the countdown has ended, and choose <b>Skip the Night</b>. It passes the whole night to dawn and does not count: no night survived, and the next dusk brings the same night again.", "<b>Cursed Essence</b> drops from every kill - spend it at the Echo Altars. Now and then a body drops a glowing token (1 kill in 50): walk into it before it blinks out (20 s). Nuke (the dead around you turn to ash), Double Essence (30 s), Refill Stats (ammo, health, magicka, stamina and your shout), Merchant's Blessing (the altars at half price, 45 s), Shadow of Nocturnal (the dead lose you, 15 s), Thu'um Unbound (no shout cooldown, 20 s) and Kynareth's Mercy (everyone healed, a fallen friend lifted). In a party, what one takes everyone gets. From dusk to dawn a lantern at your belt lights 20 metres round you. At dawn the dead leave their ash where they fell, and in a freed city its people leave an offering at their altar for you each day.", "Your health, magicka and stamina sit on one plate at the bottom; its rim glows blue while your shout recovers." } },
		{ 3, "The Echo Altar", "", { "Every city has one. Step onto it and activate it. Move with the D-pad or W/S, choose with A or Enter, leave with B.", "From the top: <b>your class</b> (change it for Cursed Essence - each class keeps its own kit and progress), a <b>Dragon Priest's relic</b> when one waits, then sections that open one at a time: <b>Your Kit</b> (select an item to upgrade it), <b>the Armory</b> (new items, opened by freed cities), <b>Perks</b>, <b>Your Dragon</b>, the city's <b>Trials</b> and the <b>Whispers</b> of your path's secret.", "<b>Freeing a city</b>: finish four trials (three shared, one your class's), then slay its <b>Dragon Priest</b>, who rises at night. Its fall ends the night and leaves a relic. A freed city is a sanctuary: none of the curse's dead rise inside it. Whiterun gives you a dragon to ride and Dragon's Updraft; Solitude gives you the Dance of Death.", "<b>Every 5th night</b> a great boss walks with the dead - and its dawn leaves a power-up at your feet." } },
		{ 3, "The Road to the Echo", "", { "<b>The Reliquary</b>: once six cities are free, your path's <b>secret</b> wakes. Win it and the Greybeards call you - your <b>wonder</b> waits on its pedestal in the Reliquary, behind the sealed door in High Hrothgar's great hall. A wonder answers only to its own path.", "<b>The three dragons</b>: with all four paths' wonders won (change class to win each, or pool them with your party), Alduin's three words wake as dragons - <b>SLEN</b> at the cult's shrine in the Reach, <b>TIID</b> at Labyrinthian, <b>VO</b> on Mount Anthor. Go at night: the dead come first, then the dragon. Each one slain gives a lasting power, and with all three dead your wonders take their <b>Legendary</b> form.", "<b>The Echo of Alduin</b>: last of all, once the three dragons are dead and every Echo Altar is awake, on the summit of the Throat of the World. Slay it and the curse is broken - the nights are only nights again, and the Reliquary becomes the <b>Hall of the Awakened</b>: Alduin's Bane, the First Dragonborn's Regalia, the Bone-Wyrm's Skull, the Brazier of the Endless Night and the Seat of the Awakened." } },
		{ 3, "Settings", "", { "<b>Difficulty</b> is Skyrim's own (Settings, Gameplay). Novice is very easy, Apprentice easy, Adept normal, Expert hard, Master very hard and Legendary close to impossible. From Novice to Legendary the dead (and Skyrim's own foes against your altar gear) have <b>0.5x, 0.75x, 1x, 1.5x, 2.2x, 3.2x</b> health, and the dead hit <b>0.4x, 0.65x, 1x, 1.4x, 1.9x, 2.6x</b> as hard. Every Echo Altar freed makes them all 30% tougher (up to ten), to keep up with your upgraded gear. Until three altars are freed, on Adept or harder, no single hit takes more than 60% of a zombie's health.", "Skyrim's own enemies get tougher with the difficulty and with every altar you free, so they keep up with you.", "The <b>Mod Configuration Menu</b> page <i>The Curse of Alduin</i> has the rest: attack and draw speed, field of view, brightness, effects and controls." } },
		{ 4, "The Spellsword", "", { "A <b>Vigilant of Stendarr</b>: steel in one hand, a touch spell in the other - fire, frost, shock, sun or blood - that rides every blow of the blade.", "<b>You start with</b> the <b>Madness Sword</b>, <b>Burning Touch</b> (left hand) and your armor set - the <b>Valkyrie Armor</b> for a woman, the <b>DragonLord Armor</b> for a man: Tier I you mend in a fight, Tier II your blade's hits put magicka back, Tier III your blade hits 15% harder. No shields: your off hand is always a spell, and every blade hit casts it." } },
		{ 4, "Your Progress", "@progress", {  } },
		{ 4, "Your Altar", "", { "<b>Your kit</b> - the blade and each spell with its tier and the price of its next upgrade.", "<b>The Armory</b> - more touch spells open as you free cities: Frost touch at 1, Shock touch at 3, Sun touch at 5, Blood touch at 7.", "<b>Dragon Priest relics</b> - every Dragon Priest you slay leaves a relic for your class. Take it at any Echo Altar. The Spellsword's relics are the old Vigilants' spells, a step above the Armory's - four close (Flame, Frost and Storm Cloaks, Stendarr's Aura) and four reaching (Vampire's Bane, the Walls of the Tempest and the Winter, the Pyre Rune). Your blade stays your own." } },
		{ 4, "Getting Stronger", "", { "<b>One curve for everything.</b> Every item in your kit climbs Base, <b>Tier I</b> (1.3 times its damage), <b>Tier II</b> (1.7 times), <b>Tier III - Legendary</b> (2.2 times), then <b>Ascends</b> (+0.3 times each). Prices: Tier I 4,000, Tier II 6,000 (needs 2 freed cities), Tier III 8,000 (4 cities), Ascend 10,000 and 2,000 more each time (6 cities). Your class's <b>armor set</b> is in your kit too: it starts at 5% damage reduction and every tier adds 5% (20% at Tier III), with a power of its own at each tier; each Ascend of the set adds 5% to all your damage." } },
		{ 4, "Your Perks", "", { "<b>Bladesong Mead</b> - each melee hit heals you 1.5%.", "<b>Spellbinder's Draught</b> - melee kills give back 6% magicka.", "<b>Steel-Wind Ale</b> - melee swings 15% faster.", "One of each perk a life - death takes them all." } },
		{ 4, "Your Trial and Wonder", "", { "<b>Trial of Steel</b> (your city trial): melee kills with a spell in your other hand - 10 on Novice up to 30 on Legendary.", "<b>Dragon Slayer</b> (your wonder): it can't be rolled or bought. Once six cities are freed, your path's <b>secret</b> wakes - a long hidden quest played from altar to altar, never twice in a row in the same city. Listen to the freed altars' whispers. When it is won the Greybeards call: the wonder waits on its pedestal in the Reliquary beneath High Hrothgar. It stands two tiers above your blade, and every hit carries the last Spellsword spell you held; once the three dragons fall it grows stronger again, and power attacks loose that spell on the dead round you." } },
		{ 4, "How a Night Works", "", { "<b>Day</b> (about 20 minutes): the dead sleep. Explore, rest and spend your Cursed Essence.", "<b>Night</b>: the dead claw up out of the ground (on open ground, never in houses) in <b>waves</b> - fast runners, more and tougher each night, coming from every side. Elites and bosses step out of the Curse's portals. Dawn only comes when the last wave falls.", "The night's dead are the curse's whole host, each under its own name: Mihail's zombies and the Thriceborn walk first with the Rag Draugr, rotten skeletons and plague wolves; then Bonemen, skeleton mages and the necromancers who serve the curse; then Hulking Draugr, Draugr Liches, Draman Brutes, Ash Spawn and werewolves; then the Daedra - Clannfear, Daedroth, Dremora - and at the last the Overlords, the Mythic Liches and the Skeleton Reaper Warlords. Casters keep back and raise more dead - kill them first.", "Some nights the noise you make draws a hunter: a feral nightwalker, far faster than the rest, that comes through a portal and pounces.", "Busy with a quest? Open the wait menu at night, once the countdown has ended, and choose <b>Skip the Night</b>. It passes the whole night to dawn and does not count: no night survived, and the next dusk brings the same night again.", "<b>Cursed Essence</b> drops from every kill - spend it at the Echo Altars. Now and then a body drops a glowing token (1 kill in 50): walk into it before it blinks out (20 s). Nuke (the dead around you turn to ash), Double Essence (30 s), Refill Stats (ammo, health, magicka, stamina and your shout), Merchant's Blessing (the altars at half price, 45 s), Shadow of Nocturnal (the dead lose you, 15 s), Thu'um Unbound (no shout cooldown, 20 s) and Kynareth's Mercy (everyone healed, a fallen friend lifted). In a party, what one takes everyone gets. From dusk to dawn a lantern at your belt lights 20 metres round you. At dawn the dead leave their ash where they fell, and in a freed city its people leave an offering at their altar for you each day.", "Your health, magicka and stamina sit on one plate at the bottom; its rim glows blue while your shout recovers." } },
		{ 4, "The Echo Altar", "", { "Every city has one. Step onto it and activate it. Move with the D-pad or W/S, choose with A or Enter, leave with B.", "From the top: <b>your class</b> (change it for Cursed Essence - each class keeps its own kit and progress), a <b>Dragon Priest's relic</b> when one waits, then sections that open one at a time: <b>Your Kit</b> (select an item to upgrade it), <b>the Armory</b> (new items, opened by freed cities), <b>Perks</b>, <b>Your Dragon</b>, the city's <b>Trials</b> and the <b>Whispers</b> of your path's secret.", "<b>Freeing a city</b>: finish four trials (three shared, one your class's), then slay its <b>Dragon Priest</b>, who rises at night. Its fall ends the night and leaves a relic. A freed city is a sanctuary: none of the curse's dead rise inside it. Whiterun gives you a dragon to ride and Dragon's Updraft; Solitude gives you the Dance of Death.", "<b>Every 5th night</b> a great boss walks with the dead - and its dawn leaves a power-up at your feet." } },
		{ 4, "The Road to the Echo", "", { "<b>The Reliquary</b>: once six cities are free, your path's <b>secret</b> wakes. Win it and the Greybeards call you - your <b>wonder</b> waits on its pedestal in the Reliquary, behind the sealed door in High Hrothgar's great hall. A wonder answers only to its own path.", "<b>The three dragons</b>: with all four paths' wonders won (change class to win each, or pool them with your party), Alduin's three words wake as dragons - <b>SLEN</b> at the cult's shrine in the Reach, <b>TIID</b> at Labyrinthian, <b>VO</b> on Mount Anthor. Go at night: the dead come first, then the dragon. Each one slain gives a lasting power, and with all three dead your wonders take their <b>Legendary</b> form.", "<b>The Echo of Alduin</b>: last of all, once the three dragons are dead and every Echo Altar is awake, on the summit of the Throat of the World. Slay it and the curse is broken - the nights are only nights again, and the Reliquary becomes the <b>Hall of the Awakened</b>: Alduin's Bane, the First Dragonborn's Regalia, the Bone-Wyrm's Skull, the Brazier of the Endless Night and the Seat of the Awakened." } },
		{ 4, "Settings", "", { "<b>Difficulty</b> is Skyrim's own (Settings, Gameplay). Novice is very easy, Apprentice easy, Adept normal, Expert hard, Master very hard and Legendary close to impossible. From Novice to Legendary the dead (and Skyrim's own foes against your altar gear) have <b>0.5x, 0.75x, 1x, 1.5x, 2.2x, 3.2x</b> health, and the dead hit <b>0.4x, 0.65x, 1x, 1.4x, 1.9x, 2.6x</b> as hard. Every Echo Altar freed makes them all 30% tougher (up to ten), to keep up with your upgraded gear. Until three altars are freed, on Adept or harder, no single hit takes more than 60% of a zombie's health.", "Skyrim's own enemies get tougher with the difficulty and with every altar you free, so they keep up with you.", "The <b>Mod Configuration Menu</b> page <i>The Curse of Alduin</i> has the rest: attack and draw speed, field of view, brightness, effects and controls." } },
		{ 5, "The Broken Words: Riverwood", "", { "<i>We raised this altar in the valley where the river runs out of the mountains, and cut the valley's words into its heart-stone. Vahlok, the cult's jailor, watched us do it from the barrow on the peak. He swore to Alduin that no prisoner of his would ever go free - and the dead, to him, are prisoners.</i>", "The Dragon Priest of Riverwood: <b>Vahlok the Jailor</b>. Vahlok kept the cult's prisoners in the Merethic Era, and his oath to Alduin was the last he swore. It has brought him out of his tomb and across the sea to the barrow above Riverwood, to keep the valley's altar dark.", "The words on the heart-stone: <b>STRUN BAH QO</b> ('Storm Wrath Lightning') - <i>Thunder Lash</i>. Activate the woken altar and choose <b>Learn the Thu'um</b>: the runes give the shout up to you, as a Word Wall would.", "<i>- set down by a Tongue of the Way of the Voice, after Jurgen Windcaller</i>" } },
		{ 6, "The Broken Words: Whiterun", "", { "<i>The plains' altar is the one Nahkriin hates most, for it stands nearest the road to Sovngarde. He kept that road for Alduin at Skuldafn. When the World-Eater's mist lies on the door, Nahkriin will come to the plains to keep it there.</i>", "The Dragon Priest of Whiterun: <b>Nahkriin, Warden of Skuldafn</b>. Nahkriin guarded Skuldafn, the gate to Sovngarde, for Alduin, and the mist that bars Sovngarde's door is his to keep. He has come down from the mountains to the plains, so that Whiterun's dead never find the way home.", "<i>- set down by a Tongue of the Way of the Voice, after Jurgen Windcaller</i>" } },
		{ 7, "The Broken Words: Solitude", "", { "<i>Volsung could breathe on the peaks where we could not, and he laughed at our altar under the cliffs of Haafingar. But the Voice carries further than breath. The runes on its heart-stone hold the words that answer him.</i>", "The Dragon Priest of Solitude: <b>Volsung of Volskygge</b>. Volsung ruled the peaks above Haafingar from Volskygge, and his mask let him breathe where no man could. He climbs down to Solitude now, and the dead of the Blue Palace's crypts rise at his word.", "The words on the heart-stone: <b>DIL VAAZ ZOL</b> ('Undead Tear Zombie') - <i>Raise the Fallen</i>. Activate the woken altar and choose <b>Learn the Thu'um</b>: the runes give the shout up to you, as a Word Wall would.", "<i>- set down by a Tongue of the Way of the Voice, after Jurgen Windcaller</i>" } },
		{ 8, "The Broken Words: Windhelm", "", { "<i>Zahkriisos was not of this land; he came over the Sea of Ghosts with the cult's fleet, and the cold came with him. We set the altar of the east by the water so that it would hear him first if he ever came back across the ice.</i>", "The Dragon Priest of Windhelm: <b>Zahkriisos the Frost-Priest</b>. Zahkriisos lay in his tomb on Solstheim until Alduin's shout crossed the Sea of Ghosts. He walked over the ice to Windhelm's docks, and the cold he carries stops a heart.", "The words on the heart-stone: <b>IIZ SLEN NUS</b> ('Ice Flesh Statue') - <i>Frost Nova</i>. Activate the woken altar and choose <b>Learn the Thu'um</b>: the runes give the shout up to you, as a Word Wall would.", "<i>- set down by a Tongue of the Way of the Voice, after Jurgen Windcaller</i>" } },
		{ 9, "The Broken Words: Markarth", "", { "<i>Even the cult feared Otar. They walled him up in Ragnvald while he still breathed. We did not trust the wall, so we raised an altar on the Reach's stone and cut into it words he could not shout down.</i>", "The Dragon Priest of Markarth: <b>Otar the Mad</b>. Otar was so cruel that his own cult sealed him alive in Ragnvald. His oath to Alduin outlived his reason. He climbs out of the Reach's stone beneath Markarth to guard its altar.", "The words on the heart-stone: <b>GOL VAH DEN</b> ('Earth Spring Hold') - <i>Dwemer Quake</i>. Activate the woken altar and choose <b>Learn the Thu'um</b>: the runes give the shout up to you, as a Word Wall would.", "<i>- set down by a Tongue of the Way of the Voice, after Jurgen Windcaller</i>" } },
		{ 10, "The Broken Words: Riften", "", { "<i>Rahgot's people drank poison sooner than see him taken. A priest who can ask that of his followers will ask it again. When he rises, the Rift's dead will come with him, and the altar must be woken to send them back.</i>", "The Dragon Priest of Riften: <b>Rahgot of Forelhost</b>. Rahgot's followers poisoned themselves in Forelhost rather than surrender him to the Tongues. They rise with him now, and the Rift's dead follow them down to Riften's altar.", "The words on the heart-stone: <b>FEIM ZII GRON</b> ('Fade Spirit Bind') - <i>Shadow Step</i>. Activate the woken altar and choose <b>Learn the Thu'um</b>: the runes give the shout up to you, as a Word Wall would.", "<i>- set down by a Tongue of the Way of the Voice, after Jurgen Windcaller</i>" } },
		{ 11, "The Broken Words: Falkreath", "", { "<i>Krosis wept for a thousand years at Shearpoint, guarding a word no one came to learn. Grief is a long oath. The altar of the pines is cut with gentler words than the rest - to put children back to sleep.</i>", "The Dragon Priest of Falkreath: <b>Krosis of Shearpoint</b>. Krosis guarded the word at Shearpoint, mourning, for a thousand years. Alduin's shout gave him something to do with his sorrow: he comes down to Falkreath's graveyard to keep its children in the ground no longer.", "The words on the heart-stone: <b>KRII LUN AUS</b> ('Kill Leech Suffer') - <i>Death's Harvest</i>. Activate the woken altar and choose <b>Learn the Thu'um</b>: the runes give the shout up to you, as a Word Wall would.", "<i>- set down by a Tongue of the Way of the Voice, after Jurgen Windcaller</i>" } },
		{ 12, "The Broken Words: Morthal", "", { "<i>Hevnoraak's own servants sealed him in Valthume, and set the seal with his blood. No seal holds against SLEN TIID VO. When the marsh fog thickens, look to the altar, and to the words on its heart-stone.</i>", "The Dragon Priest of Morthal: <b>Hevnoraak of Valthume</b>. Hevnoraak's servants sealed him in Valthume to stop him rising. The seal could not hold against SLEN TIID VO: he walks out of the marsh fog, and Hjaalmarch's drowned dead follow him.", "The words on the heart-stone: <b>ZUN HAAL VIIK</b> ('Weapon Hand Defeat') - <i>Mire Grasp</i>. Activate the woken altar and choose <b>Learn the Thu'um</b>: the runes give the shout up to you, as a Word Wall would.", "<i>- set down by a Tongue of the Way of the Voice, after Jurgen Windcaller</i>" } },
		{ 13, "The Broken Words: Dawnstar", "", { "<i>Vokun's shadows reached into men's dreams. The priests at the temple on the hill dreamed of him for a thousand years before he came. Wake the altar, and the town will sleep without dreaming of him again.</i>", "The Dragon Priest of Dawnstar: <b>Vokun of High Gate</b>. Vokun was a priest of shadows, and the Nightcaller's dreamers in Dawnstar dreamed his return a thousand years before it came. Kill him, and Dawnstar's nightmares end.", "The words on the heart-stone: <b>FAAS RU MAAR</b> ('Fear Run Terror') - <i>Nightmare Howl</i>. Activate the woken altar and choose <b>Learn the Thu'um</b>: the runes give the shout up to you, as a Word Wall would.", "<i>- set down by a Tongue of the Way of the Voice, after Jurgen Windcaller</i>" } },
		{ 14, "The Broken Words: Winterhold", "", { "<i>Morokei held the Staff of Magnus in Bromjunaar, and the mages who came after us have never forgotten him. The northern altar stands on the cliffs where the storms break; its words are cut deepest of all, for he is the strongest of them.</i>", "The Dragon Priest of Winterhold: <b>Morokei of Labyrinthian</b>. Morokei once held the Staff of Magnus in Labyrinthian, and the College has feared him ever since. He has come to the cliffs above Winterhold, and the storm he calls has not finished yet.", "The words on the heart-stone: <b>SU GRAH DUN</b> ('Air Battle Grace') - <i>Arcane Singularity</i>. Activate the woken altar and choose <b>Learn the Thu'um</b>: the runes give the shout up to you, as a Word Wall would.", "<i>- set down by a Tongue of the Way of the Voice, after Jurgen Windcaller</i>" } },
	};
}
